import { Flex } from "@chakra-ui/react";
import { useCallback, useMemo } from "react";
import { InspectorViewHeader } from "../components/InspectorViewHeader";
import { ScrollFadeArea } from "../components/ScrollFadeArea";
import { NoData } from "../Placeholder";
import { useInspectorStore, toggleSelectedElement } from "../store";
import { selectIsMantleEngine } from "../store/selectors";
import { PlaceholderImage } from "../types";
import { deriveFlowTimeline, deriveSkillTimeline, FlowTimeline } from "./FlowTimeline";

export const HistorySection = () => {
  const conversationList = useInspectorStore((s) => s.conversationList);
  const flows = useInspectorStore((s) => s.flows);
  const skillCatalog = useInspectorStore((s) => s.skillCatalog);
  const isMantleEngine = useInspectorStore(selectIsMantleEngine);
  const allEvents = useMemo(
    () => conversationList[conversationList.length - 1]?.events,
    [conversationList],
  );

  const entries = useMemo(() => {
    if (isMantleEngine) {
      const skillNames = new Map(
        Object.values(skillCatalog ?? {}).map((skill) => [
          skill.id,
          (skill.name ?? skill.id).replaceAll("_", " "),
        ]),
      );
      return deriveSkillTimeline(allEvents, skillNames);
    }
    const flowNames = new Map(flows.map((f) => [f.id, (f.name ?? f.id).replaceAll("_", " ")]));
    return deriveFlowTimeline(allEvents, flowNames);
  }, [allEvents, flows, skillCatalog, isMantleEngine]);

  // Single-block skills don't benefit from showing the block in History —
  // the skill entry alone is enough navigation, and the block row ("Block: main")
  // adds noise without giving the user an independent navigation target.
  const filteredEntries = useMemo(() => {
    if (!isMantleEngine || !skillCatalog) return entries;
    return entries.filter((entry) => {
      if (entry.type !== "block") return true;
      const parentSkill = skillCatalog[entry.skillId ?? ""];
      if (!parentSkill) return true;
      return Object.keys(parentSkill.blocks).length > 1;
    });
  }, [entries, isMantleEngine, skillCatalog]);

  const handleEntryClick = useCallback(
    (entryId: string) => {
      const event = allEvents.find((e) => e.id === entryId);
      if (event) toggleSelectedElement(event);
    },
    [allEvents],
  );

  return (
    <Flex direction="column" width="100%" height="100%" overflow="hidden">
      <InspectorViewHeader title="History" />
      <ScrollFadeArea>
        {filteredEntries.length > 0 ? (
          <FlowTimeline entries={filteredEntries} onEntryClick={handleEntryClick} />
        ) : (
          <NoData
            image={PlaceholderImage.Cubes}
            shortLabel="History"
            longLabel="Conversation history will be shown here."
          />
        )}
      </ScrollFadeArea>
    </Flex>
  );
};
